-- 203K archived-webpage snapshots flagging when a page appeared, changed, or went dead.
-- Auto-generated by scripts/gen_evidence_pages.py: 203,305 rows > 100k, so this is a BOUNDED pre-aggregate (parquet-safe by construction), not select *.
select year("CAPTURED_AT") as year, count(*) as records
from THE_LIBRARY.INVESTIGATIONS.WEB_PAGE_CHANGES
where "CAPTURED_AT" is not null
group by 1
order by 1
